/* ------------------------------------------------------------------
   KanjiGlyph — draw a character with each component's strokes in the
   colour of the job that component does IN THAT CHARACTER.

   This is the thing plain HTML cannot do. A kanji is one glyph, and CSS
   colours whole characters, so 言 inside 語 cannot be tinted as text.
   Drawing the strokes as SVG makes the parts separately addressable,
   which is what the English word builders get for free by colouring
   letters inside a word.

   Usage:
     KanjiGlyph.svg("語", [{p:"言",role:"sense"},{p:"吾",role:"sound"}], {size:64})

   The roles come from the CALLER, never from this file. Pass the tool's
   own parts array and the colours follow whatever that tool has vetted.
   ------------------------------------------------------------------ */
window.KanjiGlyph = (function () {
  "use strict";
  var DEFAULT = {
    sense: "var(--sense)", sound: "var(--sound)", both: "var(--both)",
    none: "var(--muted)", okuri: "var(--muted)"
  };
  function has(ch) { return Object.prototype.hasOwnProperty.call(KVG, ch); }

  function svg(ch, parts, opts) {
    if (!has(ch)) return "";
    opts = opts || {};
    var size = opts.size || 56;
    var colors = Object.assign({}, DEFAULT, opts.colors || {});
    var flat = opts.mono || null;           // one colour for every stroke
    var roleOf = {};
    (parts || []).forEach(function (p) { roleOf[p.p] = p.role; });

    var paths = KVG[ch].map(function (g) {
      var part = g[0], role = part ? roleOf[part] : null;
      var col = flat || colors[role || "none"] || colors.none;
      var title = part ? '<title>' + part + (role ? " · " + role : "") + '</title>' : "";
      return g[1].split("|").map(function (d) {
        return '<path d="' + d + '" stroke="' + col + '">' + title + '</path>';
      }).join("");
    }).join("");

    return '<svg class="kglyph" viewBox="0 0 109 109" width="' + size + '" height="' + size +
      '" role="img" aria-label="' + ch + '" fill="none" stroke-width="' +
      (opts.weight || 4.5) + '" stroke-linecap="round" stroke-linejoin="round">' + paths + '</svg>';
  }
  return { has: has, svg: svg, chars: function () { return Object.keys(KVG); } };
})();
